  .addNode("generate_joke", (state) => ({
    jokes: [`Joke about ${state.subjects}`],
  }))
  .addConditionalEdges("__start__", fanOut)
  .addEdge("generate_joke", "__end__")
  .compile();

const result = await graph.invoke({ subjects: ["cats", "dogs"] });
console.log(result);

